module MOLECULE_ISOTOP
 type isotop
	integer      :: id_molecule, id_isotop
	character(4) :: name_molecule
 end type isotop
 contains
 function get_id(iso)
	integer   , intent(in)   :: iso
	type(isotop) :: get_id
	get_id.id_molecule = 0; get_id.name_molecule = ''; get_id.id_isotop = 0
	select case(iso)
		case(11,12,13,14,15,16,17)
			get_id.name_molecule = 'H2O '; get_id.id_molecule = 1
			if(iso == 11) get_id.id_isotop = 1
			if(iso == 12) get_id.id_isotop = 2
			if(iso == 13) get_id.id_isotop = 3
			if(iso == 14) get_id.id_isotop = 4
			if(iso == 15) get_id.id_isotop = 5
			if(iso == 16) get_id.id_isotop = 6
			if(iso == 17) get_id.id_isotop = 7
		case(21,22,23,24,25,26,27,28,29,20,211,212)
			get_id.name_molecule = 'CO2 '; get_id.id_molecule = 2
			if(iso == 21) get_id.id_isotop = 1
			if(iso == 22) get_id.id_isotop = 2
			if(iso == 23) get_id.id_isotop = 3
			if(iso == 24) get_id.id_isotop = 4
			if(iso == 25) get_id.id_isotop = 5
			if(iso == 26) get_id.id_isotop = 6
			if(iso == 27) get_id.id_isotop = 7
			if(iso == 28) get_id.id_isotop = 8
			if(iso == 29) get_id.id_isotop = 9
			if(iso == 20) get_id.id_isotop = 10
			if(iso == 211) get_id.id_isotop = 11
			if(iso == 212) get_id.id_isotop = 12
		case(31,32,33,34,35)
			get_id.name_molecule = 'O3  '; get_id.id_molecule = 3
			if(iso == 31) get_id.id_isotop = 1
			if(iso == 32) get_id.id_isotop = 2
			if(iso == 33) get_id.id_isotop = 3
			if(iso == 34) get_id.id_isotop = 4
			if(iso == 35) get_id.id_isotop = 5
		case(41,42,43,44,45)
			get_id.name_molecule = 'N2O '; get_id.id_molecule = 4
			if(iso == 41) get_id.id_isotop = 1
			if(iso == 42) get_id.id_isotop = 2
			if(iso == 43) get_id.id_isotop = 3
			if(iso == 44) get_id.id_isotop = 4
			if(iso == 45) get_id.id_isotop = 5
		case(51,52,53,54,55,56)
			get_id.name_molecule = 'CO  '; get_id.id_molecule = 5
			if(iso == 51) get_id.id_isotop = 1
			if(iso == 52) get_id.id_isotop = 2
			if(iso == 53) get_id.id_isotop = 3
			if(iso == 54) get_id.id_isotop = 4
			if(iso == 55) get_id.id_isotop = 5
			if(iso == 56) get_id.id_isotop = 6
		case(61,62,63,64)
			get_id.name_molecule = 'CH4 '; get_id.id_molecule = 6
			if(iso == 61) get_id.id_isotop = 1
			if(iso == 62) get_id.id_isotop = 2
			if(iso == 63) get_id.id_isotop = 3
			if(iso == 64) get_id.id_isotop = 4
		case(71,72,73)
			get_id.name_molecule = 'O2  '; get_id.id_molecule = 7
			if(iso == 71) get_id.id_isotop = 1
			if(iso == 72) get_id.id_isotop = 2
			if(iso == 73) get_id.id_isotop = 3
		case(131,132,133)
			get_id.name_molecule = 'OH  '; get_id.id_molecule = 8
			if(iso == 131) get_id.id_isotop = 1
			if(iso == 132) get_id.id_isotop = 2
			if(iso == 133) get_id.id_isotop = 3
		case(221,222)
			get_id.name_molecule = 'N2  '; get_id.id_molecule = 9
			if(iso == 221) get_id.id_isotop = 1
			if(iso == 222) get_id.id_isotop = 2
	end select
 end function get_id
end module MOLECULE_ISOTOP

